"""Atomic and immutable JSON artifacts only; no consultation trajectory layer."""

from __future__ import annotations

import json
import os
import re
import tempfile
from pathlib import Path
from typing import Any

from legal_skill_guard.utils.hashing import canonical_json_sha256


class ImmutableArtifactConflictError(FileExistsError):
    """An immutable artifact path already contains different JSON content."""


def safe_component(value: str) -> str:
    normalized = re.sub(r"[^a-zA-Z0-9_.-]+", "_", value).strip("_.-")
    if not normalized or normalized != value:
        raise ValueError(f"Unsafe artifact path component: {value!r}")
    return normalized


class RunStore:
    @staticmethod
    def atomic_json(path: Path, value: Any) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_suffix(path.suffix + ".tmp")
        temporary.write_text(
            json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        temporary.replace(path)

    @staticmethod
    def immutable_json(path: Path, value: Any) -> Path:
        """Create a JSON artifact once, allowing only content-identical retries.

        Equality is based on canonical JSON rather than whitespace or dictionary
        insertion order.  Creation uses an exclusive hard-link commit so two
        concurrent writers cannot silently replace one another.
        """

        expected_sha256 = canonical_json_sha256(value)
        path.parent.mkdir(parents=True, exist_ok=True)

        def validate_existing() -> Path:
            try:
                existing = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ImmutableArtifactConflictError(
                    f"immutable JSON artifact is unreadable: {path}: {exc}"
                ) from exc
            actual_sha256 = canonical_json_sha256(existing)
            if actual_sha256 != expected_sha256:
                raise ImmutableArtifactConflictError(
                    "immutable JSON artifact conflict: "
                    f"{path} existing_sha256={actual_sha256} "
                    f"requested_sha256={expected_sha256}"
                )
            return path

        if path.exists():
            return validate_existing()

        serialized = json.dumps(value, ensure_ascii=False, indent=2) + "\n"
        temporary_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="w",
                encoding="utf-8",
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".tmp",
                delete=False,
            ) as temporary:
                temporary.write(serialized)
                temporary.flush()
                os.fsync(temporary.fileno())
                temporary_path = Path(temporary.name)
            try:
                os.link(temporary_path, path)
            except FileExistsError:
                return validate_existing()
            return path
        finally:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)

"""Local vLLM transport and native generation types; no replay cache."""

from __future__ import annotations

import json
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any
from urllib import error, request


@dataclass(frozen=True)
class GenerationConfig:
    temperature: float
    top_p: float
    max_tokens: int
    seed: int
    disable_thinking: bool = True
    reasoning_effort: str | None = None
    response_schema: dict[str, Any] | None = None
    response_schema_name: str = "local_structured_response"
    top_k: int | None = None


@dataclass(frozen=True)
class ChatResponse:
    content: str
    finish_reason: str | None
    prompt_tokens: int
    completion_tokens: int
    raw_id: str | None


class ChatClient:
    def __init__(
        self,
        base_url: str,
        model: str,
        api_key: str = "local-research",
        timeout_seconds: float = 600.0,
        retries: int = 2,
        expected_model_root: str | Path | None = None,
        expected_max_model_len: int | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.api_key = api_key
        self.timeout_seconds = timeout_seconds
        self.retries = retries
        self.expected_model_root = (
            str(Path(expected_model_root).resolve()) if expected_model_root is not None else None
        )
        self.expected_max_model_len = expected_max_model_len
        # Research servers are loopback-only. Never route hidden prompts or responses
        # through a workstation-wide HTTP(S) proxy.
        self.opener = request.build_opener(request.ProxyHandler({}))

    def _request(self, method: str, path: str, payload: dict[str, Any] | None = None) -> Any:
        body = json.dumps(payload, ensure_ascii=False).encode() if payload is not None else None
        headers = {"Authorization": f"Bearer {self.api_key}"}
        if body is not None:
            headers["Content-Type"] = "application/json"
        req = request.Request(f"{self.base_url}{path}", data=body, headers=headers, method=method)
        last_error: Exception | None = None
        for attempt in range(self.retries + 1):
            try:
                with self.opener.open(req, timeout=self.timeout_seconds) as response:
                    return json.loads(response.read().decode("utf-8"))
            except error.HTTPError as exc:
                # vLLM returns the actionable schema/context rejection in the
                # response body. Preserve a bounded local-only diagnostic;
                # discarding it turned deterministic 400s into opaque failures.
                try:
                    detail = exc.read().decode("utf-8", errors="replace")[:4_000]
                except OSError:
                    detail = ""
                last_error = RuntimeError(
                    f"HTTP {exc.code} {exc.reason}: {detail or '<empty response body>'}"
                )
                if attempt >= self.retries:
                    break
                time.sleep(0.5 * (2**attempt))
            except (error.URLError, TimeoutError, json.JSONDecodeError) as exc:
                last_error = exc
                if attempt >= self.retries:
                    break
                time.sleep(0.5 * (2**attempt))
        raise RuntimeError(f"Local model request failed: {last_error}") from last_error

    def readiness(self) -> dict[str, Any]:
        try:
            response = self._request("GET", "/models")
        except RuntimeError as exc:
            return {"ready": False, "reason": type(exc.__cause__ or exc).__name__}
        cards = [item for item in response.get("data", []) if item.get("id") == self.model]
        if len(cards) != 1:
            return {
                "ready": False,
                "reason": "model_card_not_unique",
                "matching_model_card_count": len(cards),
            }
        card = cards[0]
        observed_root = card.get("root")
        normalized_root = (
            str(Path(str(observed_root)).resolve())
            if observed_root is not None and self.expected_model_root is not None
            else observed_root
        )
        observed_max_model_len = card.get("max_model_len")
        checks = {
            "model_id_matches": card.get("id") == self.model,
            "model_root_matches": self.expected_model_root is None
            or normalized_root == self.expected_model_root,
            "max_model_len_matches": self.expected_max_model_len is None
            or observed_max_model_len == self.expected_max_model_len,
        }
        failed = [name for name, passed in checks.items() if not passed]
        return {
            "ready": not failed,
            "reason": "model_contract_matches" if not failed else "model_contract_mismatch",
            "model": self.model,
            "observed_model_root": normalized_root,
            "expected_model_root": self.expected_model_root,
            "observed_max_model_len": observed_max_model_len,
            "expected_max_model_len": self.expected_max_model_len,
            "checks": checks,
            "failed_checks": failed,
        }

    def is_ready(self) -> bool:
        return bool(self.readiness()["ready"])

    def generate(
        self, messages: list[dict[str, str]], generation: GenerationConfig
    ) -> ChatResponse:
        payload: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": generation.temperature,
            "top_p": generation.top_p,
            "max_tokens": generation.max_tokens,
            "seed": generation.seed,
        }
        if generation.disable_thinking:
            payload["chat_template_kwargs"] = {"enable_thinking": False}
        if generation.top_k is not None:
            payload["top_k"] = generation.top_k
        if generation.reasoning_effort is not None:
            payload["reasoning_effort"] = generation.reasoning_effort
        if generation.response_schema is not None:
            payload["response_format"] = {
                "type": "json_schema",
                "json_schema": {
                    "name": generation.response_schema_name,
                    "strict": True,
                    "schema": generation.response_schema,
                },
            }
        response = self._request("POST", "/chat/completions", payload)
        choices = response.get("choices") or []
        if not choices:
            raise RuntimeError(f"Local model returned no choices: {response}")
        # An empty assistant body is a completed, provenance-bearing model output,
        # not a transport failure.  Preserve its finish reason, usage and response
        # id so the calling role can record it and spend that role's bounded repair
        # attempt.  Raising here bypassed every planner/policy/client/memo repair
        # loop and turned one auditable malformed completion into a batch-wide hard
        # failure.  A response without ``choices`` remains a protocol hard error.
        content = choices[0].get("message", {}).get("content") or ""
        usage = response.get("usage") or {}
        return ChatResponse(
            content=content.strip(),
            finish_reason=choices[0].get("finish_reason"),
            prompt_tokens=int(usage.get("prompt_tokens") or 0),
            completion_tokens=int(usage.get("completion_tokens") or 0),
            raw_id=response.get("id"),
        )

"""Independent original-membership audit recovered from the Oct13 auditor."""

import json
import math

from jsonschema import validate

CLASSES = ["Entailment", "Contradiction", "NotMentioned"]


def close(expected, actual):
    if type(expected) is bool or expected is None or isinstance(expected, str):
        assert expected == actual, (expected, actual)
    elif isinstance(expected, (int, float)):
        assert isinstance(actual, (int, float)) and math.isclose(
            expected, actual, rel_tol=1e-12, abs_tol=1e-12
        ), (expected, actual)
    elif isinstance(expected, dict):
        for k, v in expected.items():
            assert k in actual, k
            close(v, actual[k])
    elif isinstance(expected, list):
        assert isinstance(actual, list) and len(expected) == len(actual)
        for a, b in zip(expected, actual):
            close(a, b)
    else:
        assert expected == actual


def original_score(response, row, annotations, keys):
    parsed, valid = None, False
    one = {
        "type": "object",
        "additionalProperties": True,
        "required": ["choice", "spans"],
        "properties": {
            "choice": {"type": "string", "enum": CLASSES},
            "spans": {
                "type": "array",
                "items": {"type": "integer", "enum": list(range(len(row["spans"])))},
            },
        },
    }
    try:
        if response["finish_reason"] != "stop":
            raise ValueError("Incomplete original public answer")
        parsed = json.loads(response["content"])
        validate(
            parsed,
            {
                "type": "object",
                "additionalProperties": False,
                "required": keys,
                "properties": {k: one for k in keys},
            },
        )
        valid = True
    except Exception:
        pass
    qq = []
    for k in keys:
        g, p = annotations[k], parsed[k] if valid else None
        gs, ps = set(g["spans"]), set(p["spans"]) if valid else set()
        nn = g["choice"] != "NotMentioned"
        assert g["choice"] in CLASSES and bool(gs) == nn
        assert all(type(s) is int and 0 <= s < len(row["spans"]) for s in gs)
        tp, fp, fn = len(gs & ps), len(ps - gs), len(gs - ps)
        f1 = 2 * tp / (2 * tp + fp + fn) if nn else None
        correct = bool(valid and p["choice"] == g["choice"])
        qq.append(
            {
                "hypothesis_id": k,
                "gold": g,
                "prediction": p,
                "label_correct": correct,
                "gold_non_neutral": nn,
                "evidence_tp": tp,
                "evidence_fp": fp,
                "evidence_fn": fn,
                "evidence_f1_gold_non_neutral": f1,
                "joint_exact": bool(correct and ps == gs),
                "joint_soft": float(correct) * f1 if nn else float(correct and not ps),
            }
        )
    return {"parsed": parsed, "public_valid": valid, "queries": qq}

"""Teacher-only, readable lossless catalogs. No training/inference decisions."""

import json
from collections import Counter
from copy import deepcopy

from .packing import unpack_cases

LEGEND = (
    "Lossless teacher catalogs v2. Every original source remains verbatim. "
    "An object containing only text_ref is exactly the verbatim_text_catalog "
    "entry at that zero-based index, not a summary. Table columns_ref refers "
    "to the ordered column_catalog entry. Expand those two references first. "
    "actual_global_query_bodies stores all exact query bodies in an ordered "
    "record table. Each plan generic_queries and receipt actual_query_arguments "
    "is a zero-based row reference to this global query table, not a case-local "
    "table. Each observation still has its own receipt table; identical receipt "
    "rows are stored once, but every hypothesis invocation and generic action "
    "retains its ordered row references, including repeated actions. Then "
    "apply the original lossless_teacher_encoding instructions in body. "
    "No source, annotation, public observation, feedback, historical bank, "
    "duplicate action, or ordering is removed. No-match is not a legal label."
)


def canonical(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def encode_teacher_body(original):
    body = deepcopy(original)
    global_queries, query_lookup = [], {}
    query_columns = None
    for case in body["all_seen_train_cases"]:
        local_table = case.pop("actual_query_bodies")
        local_refs = []
        if local_table:
            if query_columns is None:
                query_columns = local_table["columns"]
            if local_table["columns"] != query_columns:
                raise ValueError("Incompatible actual query columns; no repair")
            for row in local_table["rows"]:
                identity = canonical(row)
                if identity not in query_lookup:
                    query_lookup[identity] = len(global_queries)
                    global_queries.append(deepcopy(row))
                local_refs.append(query_lookup[identity])
        for field in (
            "actual_before_publication_observations",
            "actual_prior_post_publication_observations",
        ):
            for obs in case[field]:
                plan = obs["actual_plan"]
                column = plan["columns"].index("generic_queries")
                for row in plan["rows"]:
                    row[column] = [local_refs[i] for i in row[column]]
                trace = obs["actual_factual_trace"]
                receipts = trace["receipts"]
                if not receipts:
                    continue
                column = receipts["columns"].index("actual_query_arguments")
                unique, lookup, refs = [], {}, []
                for row in receipts["rows"]:
                    row[column] = local_refs[row[column]]
                    identity = canonical(row)
                    if identity not in lookup:
                        lookup[identity] = len(unique)
                        unique.append(deepcopy(row))
                    refs.append(lookup[identity])
                receipts["rows"] = unique
                by_h = trace["by_hypothesis"]
                skill_col = by_h["columns"].index("published_skill_invocations")
                generic_col = by_h["columns"].index("explicit_generic_query_receipts")
                for row in by_h["rows"]:
                    row[generic_col] = [refs[i] for i in row[generic_col]]
                    invocations = row[skill_col]
                    if invocations:
                        inv_col = invocations["columns"].index("receipts")
                        for invocation in invocations["rows"]:
                            invocation[inv_col] = [refs[i] for i in invocation[inv_col]]
    query_table = (
        {"encoding": "record-table-v1", "columns": query_columns, "rows": global_queries}
        if global_queries
        else []
    )
    body["actual_global_query_bodies"] = query_table
    columns, column_lookup = [], {}

    def share_columns(value):
        if isinstance(value, list):
            return [share_columns(v) for v in value]
        if not isinstance(value, dict):
            return value
        result = {k: share_columns(v) for k, v in value.items()}
        if value.get("encoding") in ("record-table-v1", "keyed-record-table-v1"):
            identity = canonical(value["columns"])
            if identity not in column_lookup:
                column_lookup[identity] = len(columns)
                columns.append(deepcopy(value["columns"]))
            result.pop("columns")
            result["columns_ref"] = column_lookup[identity]
        return result

    body = share_columns(body)
    counts = Counter()
    plain_fields = {"encoding", "original_full_contract_with_spans", "lossless_teacher_encoding"}

    def count_text(value):
        if isinstance(value, str):
            counts[value] += 1
        elif isinstance(value, list):
            for item in value:
                count_text(item)
        elif isinstance(value, dict):
            if set(value) == {"text_ref"}:
                raise ValueError("Reserved text-reference object in original data")
            for key, item in value.items():
                if key not in plain_fields:
                    count_text(item)

    count_text(body)
    texts = [
        s
        for s, n in counts.items()
        if len(s) >= 20 and n > 1 and (len(canonical(s)) - 18) * (n - 1) > len(canonical(s)) + 4
    ]
    text_lookup = {s: i for i, s in enumerate(texts)}

    def share_text(value):
        if isinstance(value, str):
            return {"text_ref": text_lookup[value]} if value in text_lookup else value
        if isinstance(value, list):
            return [share_text(v) for v in value]
        if isinstance(value, dict):
            return {k: (v if k in plain_fields else share_text(v)) for k, v in value.items()}
        return value

    payload = {
        "encoding": "lossless-teacher-catalog-v2",
        "legend": LEGEND,
        "column_catalog": columns,
        "verbatim_text_catalog": texts,
        "body": share_text(body),
    }
    expected = deepcopy(original)
    expected["all_seen_train_cases"] = unpack_cases(expected["all_seen_train_cases"])
    if decode_teacher_body(payload) != expected:
        raise ValueError("Complete teacher source/observations/history roundtrip differs")
    return payload


def decode_teacher_body(payload):
    if payload["encoding"] != "lossless-teacher-catalog-v2":
        raise ValueError("Unexpected encoding")

    def restore(value):
        if isinstance(value, list):
            return [restore(v) for v in value]
        if not isinstance(value, dict):
            return value
        if set(value) == {"text_ref"}:
            return deepcopy(payload["verbatim_text_catalog"][value["text_ref"]])
        result = {k: restore(v) for k, v in value.items() if k != "columns_ref"}
        if "columns_ref" in value:
            result["columns"] = deepcopy(payload["column_catalog"][value["columns_ref"]])
        return result

    body = restore(payload["body"])
    queries = body.pop("actual_global_query_bodies")
    for case in body["all_seen_train_cases"]:
        case["actual_query_bodies"] = deepcopy(queries)
    body["all_seen_train_cases"] = unpack_cases(body["all_seen_train_cases"])
    return body

"""Factual source-only clause operations used by the published-query executor.

Only search/return original source records. Never decide legal labels, infer
facts, read annotations, repair native answers or choose skills for the lawyer.
Tokenizer/stemmer adapted from MIT-licensed ScienceClaw scilib/contracts.py,
commit e925f732c7ca435f557e88075bc47a58f1e984f1. Full notice in LICENSE.
No neural models, embeddings, trained classifier, file/network/tool execution.
"""

from __future__ import annotations

import hashlib
import json
import re

_WORD = re.compile(r"[a-z]+(?:'[a-z]+)?|\d+")
_SUFFIXES = (
    "ations",
    "ation",
    "ingly",
    "ments",
    "ment",
    "ings",
    "ing",
    "ies",
    "ied",
    "ers",
    "ed",
    "es",
    "ly",
    "s",
)


def _stem(word):
    if len(word) > 5:
        for suffix in _SUFFIXES:
            if word.endswith(suffix) and len(word) - len(suffix) >= 4:
                return word[: -len(suffix)]
    return word


def _tokens(text):
    # Preserve negation/modality: never use the author's stopword removal here.
    return tuple(_stem(word) for word in _WORD.findall(text.lower()))


def _contains(sequence, phrase):
    return any(
        sequence[i : i + len(phrase)] == phrase for i in range(len(sequence) - len(phrase) + 1)
    )


def _terms(values):
    if not isinstance(values, list) or len(values) > 32:
        raise ValueError("A term list must contain at most32 phrases; no truncation")
    result = []
    for phrase in values:
        if not isinstance(phrase, str) or not 0 < len(phrase) <= 256:
            raise ValueError("Each phrase must be nonempty and at most256 characters")
        tokens = _tokens(phrase)
        if not tokens:
            raise ValueError("A phrase must contain word/number tokens")
        result.append(tokens)
    return result


def original_clause_records(row):
    text, spans = row["text"], row["spans"]
    records = []
    for index, pair in enumerate(spans):
        if len(pair) != 2 or any(type(v) is not int for v in pair):
            raise ValueError("Original span coordinates must be integer pairs")
        start, end = pair
        if not 0 <= start <= end <= len(text):
            raise ValueError("Original span outside its source")
        records.append(
            {
                "original_span_index": index,
                "start": start,
                "end": end,
                "literal_original_text": text[start:end],
            }
        )
    return records


def find_original_clauses(records, all_phrases, any_phrases, none_phrases):
    """Mechanical ordered stem-token matches, not a relevance/semantic oracle."""
    all_terms, any_terms, none_terms = map(_terms, (all_phrases, any_phrases, none_phrases))
    if not all_terms and not any_terms:
        raise ValueError("No empty catch-all/default query")
    hits = []
    for record in records:
        sequence = _tokens(record["literal_original_text"])
        if (
            all(_contains(sequence, p) for p in all_terms)
            and (not any_terms or any(_contains(sequence, p) for p in any_terms))
            and not any(_contains(sequence, p) for p in none_terms)
        ):
            hits.append(record["original_span_index"])
    return hits


def context_original_clauses(records, anchor_indices, before, after):
    """Explicit neighbour access; no guessed semantic boundary or clipping."""
    if any(type(v) is not int or not 0 <= v <= 64 for v in (before, after)):
        raise ValueError("Context counts must be integers in0..64")
    indices = set()
    for anchor in anchor_indices:
        if type(anchor) is not int or not 0 <= anchor < len(records):
            raise ValueError("Anchor is not an original source span")
        indices.update(range(max(0, anchor - before), min(len(records), anchor + after + 1)))
    return [records[index] for index in sorted(indices)]


def execute_clause_queries(row, queries):
    """Execute the lawyer's bounded query arguments and log literal provenance.

    Only text and original span coordinates are read, even if a caller's row
    contains extra benchmark fields. Empty matches are returned unchanged, not
    substituted by another query/result. Nothing here maps observations to E/C/N.
    """
    if not isinstance(queries, list) or len(queries) > 128:
        raise ValueError("At most128 queries; no silent truncation")
    records = original_clause_records(row)
    source_hash = hashlib.sha256(
        json.dumps(
            {"text": row["text"], "spans": row["spans"]}, ensure_ascii=False, separators=(",", ":")
        ).encode()
    ).hexdigest()
    expected = {"query_id", "all_phrases", "any_phrases", "none_phrases", "before", "after"}
    ids = set()
    trace = []
    for query in queries:
        if set(query) != expected:
            raise ValueError("Exact public query fields required")
        key = query["query_id"]
        if not isinstance(key, str) or not 0 < len(key) <= 128 or key in ids:
            raise ValueError("Distinct nonempty query IDs required")
        ids.add(key)
        hits = find_original_clauses(
            records, query["all_phrases"], query["any_phrases"], query["none_phrases"]
        )
        context = context_original_clauses(records, hits, query["before"], query["after"])
        trace.append(
            {
                "query_id": key,
                "actual_query_arguments": query,
                "source_text_and_span_sha256": source_hash,
                "matched_original_span_indices": hits,
                "context_original_clauses": context,
                "no_match_is_not_a_legal_label": True,
            }
        )
    return trace

"""Lossless receipt encoding shared by the current solver and teacher pipeline.

Remove repeated audit hashes/constants and a duplicate published-query copy.
Every actual invocation, argument, match and original context index survives.
No result selection, recomputation, deduplication, legal verdict or repair.
"""

from copy import deepcopy


def encode_receipts(compact_trace):
    data = deepcopy(compact_trace)
    source_hashes = set()

    def encode_one(receipt):
        if receipt["no_match_is_not_a_legal_label"] is not True:
            raise ValueError("Unexpected receipt semantics; no conversion")
        source_hashes.add(receipt.pop("source_text_and_span_sha256"))
        receipt.pop("no_match_is_not_a_legal_label")
        if receipt["actual_query_arguments"].pop("query_id") != receipt["query_id"]:
            raise ValueError("Actual query identity differs; no repair")

    for record in data.values():
        for invocation in record["published_skill_invocations"]:
            expected = [
                {k: v for k, v in r["actual_query_arguments"].items() if k != "query_id"}
                for r in invocation["receipts"]
            ]
            if invocation["exact_published_queries"] != expected:
                raise ValueError("Published recipe differs from actual executed bodies")
            invocation.pop("exact_published_queries")
            for receipt in invocation["receipts"]:
                encode_one(receipt)
        for receipt in record["explicit_generic_query_receipts"]:
            encode_one(receipt)
    if len(source_hashes) > 1:
        raise ValueError("One complete original document required; no source mixing")
    return {
        "encoding": "lossless-factual-receipts-v1",
        "source_text_and_span_sha256": next(iter(source_hashes), None),
        "no_match_is_not_a_legal_label": True,
        "by_hypothesis": data,
    }


def decode_receipts(encoded):
    if encoded["encoding"] != "lossless-factual-receipts-v1":
        raise ValueError("Wrong encoding contract")
    data = deepcopy(encoded["by_hypothesis"])

    def decode_one(receipt):
        receipt["source_text_and_span_sha256"] = encoded["source_text_and_span_sha256"]
        receipt["no_match_is_not_a_legal_label"] = encoded["no_match_is_not_a_legal_label"]
        receipt["actual_query_arguments"]["query_id"] = receipt["query_id"]

    for record in data.values():
        for invocation in record["published_skill_invocations"]:
            for receipt in invocation["receipts"]:
                decode_one(receipt)
            invocation["exact_published_queries"] = [
                {k: v for k, v in r["actual_query_arguments"].items() if k != "query_id"}
                for r in invocation["receipts"]
            ]
        for receipt in record["explicit_generic_query_receipts"]:
            decode_one(receipt)
    return data


def lean_final_messages(messages):
    """Same full source, guidance, queries and actual receipts; encoding only."""
    import json

    copied = deepcopy(messages)
    body = json.loads(copied[1]["content"])
    original = body["actual_factual_query_execution"]
    encoded = encode_receipts(original)
    if decode_receipts(encoded) != original:
        raise ValueError("Lossless roundtrip failed")
    body["actual_factual_query_execution"] = encoded
    copied[1]["content"] = json.dumps(body, ensure_ascii=False, separators=(",", ":"))
    copied[0]["content"] += (
        " Receipt encoding is lossless-factual-receipts-v1. by_hypothesis holds "
        "the same actual skill and generic-query executions. All actual query "
        "arguments, matches and context indices are unchanged. The source hash "
        "and no-match semantics are written once for this complete document. "
        "The exact published query bodies are already present as each executed "
        "receipt actual_query_arguments; query_id is written once per receipt. "
        "These are factual matches, never legal relevance or a legal verdict."
    )
    return copied

