def skill_record_schema(public_ids, *, guidance_schema=None):
    return {
        "type": "object",
        "additionalProperties": False,
        "required": ["id", "hypothesis_ids", "guidance"],
        "properties": {
            "id": {"type": "string", "minLength": 1},
            "hypothesis_ids": {
                "type": "array",
                "minItems": 1,
                "items": {"type": "string", "enum": list(public_ids)},
            },
            "guidance": {"type": "string", "minLength": 1}
            if guidance_schema is None
            else guidance_schema,
        },
    }


def differential_schema(public_ids, parent, seen_ids, *, guidance_schema=None):
    targets = {"type": "array", "items": {"type": "string"}}
    if parent:
        targets["items"]["enum"] = [s["id"] for s in parent]
    else:
        targets["maxItems"] = 0
    return {
        "type": "object",
        "additionalProperties": False,
        "required": ["operations", "noop_reason"],
        "properties": {
            "operations": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": [
                        "operation",
                        "target_ids",
                        "skill",
                        "source_case_ids",
                        "rationale",
                    ],
                    "properties": {
                        "operation": {
                            "type": "string",
                            "enum": ["CREATE", "UPDATE", "DELETE", "MERGE"],
                        },
                        "target_ids": targets,
                        "skill": {
                            "anyOf": [
                                skill_record_schema(public_ids, guidance_schema=guidance_schema),
                                {"type": "null"},
                            ]
                        },
                        "source_case_ids": {
                            "type": "array",
                            "minItems": 1,
                            "items": {"type": "integer", "enum": list(seen_ids)},
                        },
                        "rationale": {"type": "string", "minLength": 1},
                    },
                },
            },
            "noop_reason": {"type": ["string", "null"]},
        },
    }


def apply_differential_publication(parent, value, public_ids, seen_ids, *, guidance_schema=None):
    """Structural all-or-stop editing, never a legal judge or efficacy gate."""
    validate(
        value,
        differential_schema(public_ids, parent, seen_ids, guidance_schema=guidance_schema),
    )
    operations, noop = value["operations"], value["noop_reason"]
    if (not operations and not (noop or "").strip()) or (operations and noop is not None):
        raise ValueError("Explicit NOOP is required exactly when there are no operations")
    old = {s["id"]: s for s in parent}
    if len(old) != len(parent):
        raise ValueError("Duplicate parent IDs")
    updated = json.loads(json.dumps(old, ensure_ascii=False))
    consumed, produced = set(), set()
    for op in operations:
        kind, targets, candidate = op["operation"], op["target_ids"], op["skill"]
        refs = op["source_case_ids"]
        if len(refs) != len(set(refs)):
            raise ValueError("Duplicate source references; no repair")
        if (
            len(targets) != len(set(targets))
            or not set(targets) <= old.keys()
            or consumed & set(targets)
        ):
            raise ValueError("Targets must be unique, unconsumed exact-parent IDs")
        if (
            (kind == "CREATE" and targets)
            or (kind in ("UPDATE", "DELETE") and len(targets) != 1)
            or (kind == "MERGE" and len(targets) < 2)
        ):
            raise ValueError("Operation target arity differs from publication contract")
        if (kind == "DELETE") != (candidate is None):
            raise ValueError("Only DELETE has a null resulting skill")
        if candidate is not None:
            sid, scope = candidate["id"], candidate["hypothesis_ids"]
            if len(scope) != len(set(scope)):
                raise ValueError("Duplicate public scope; no deduplication")
            if kind == "UPDATE" and sid != targets[0]:
                raise ValueError("UPDATE must preserve the parent ID")
            if sid in produced or (sid in old and sid not in targets):
                raise ValueError("Resulting ID collides with another original or new skill")
            produced.add(sid)
        consumed.update(targets)
        if kind == "UPDATE":
            updated[targets[0]] = candidate
        else:
            for sid in targets:
                del updated[sid]
            if candidate is not None:
                updated[candidate["id"]] = candidate
    return list(updated.values())


def paired(before: list[dict], after: list[dict]) -> dict:
    a, b = (
        {(r["document_id"], q["hypothesis_id"]): q for r in rr for q in r["queries"]}
        for rr in (before, after)
    )
    if set(a) != set(b):
        raise ValueError("Original tasks are not paired")
    fixes = [list(k) for k in a if not a[k]["label_correct"] and b[k]["label_correct"]]
    breaks = [list(k) for k in a if a[k]["label_correct"] and not b[k]["label_correct"]]
    return {
        "original_hypotheses": len(a),
        "label_corrected": fixes,
        "label_broken": breaks,
        "net_label_correct": len(fixes) - len(breaks),
        "joint_exact_corrected": [
            list(k) for k in a if not a[k]["joint_exact"] and b[k]["joint_exact"]
        ],
        "joint_exact_broken": [
            list(k) for k in a if a[k]["joint_exact"] and not b[k]["joint_exact"]
        ],
    }


def publication_statistics(parent, value, bank, tokens):
    """Describe an applied edit, never select it or infer skill efficacy."""
    old, new = ({s["id"]: s for s in records} for records in (parent, bank))
    return {
        "operation_counts": {
            kind: sum(o["operation"] == kind for o in value["operations"])
            for kind in ("CREATE", "UPDATE", "DELETE", "MERGE")
        },
        "explicit_noop": not value["operations"],
        "parent_skill_count": len(parent),
        "published_skill_count": len(bank),
        "new_ids": sorted(new.keys() - old.keys()),
        "removed_ids": sorted(old.keys() - new.keys()),
        "verbatim_retained_ids": sorted(
            sid for sid in old.keys() & new.keys() if old[sid] == new[sid]
        ),
        "revised_retained_ids": sorted(
            sid for sid in old.keys() & new.keys() if old[sid] != new[sid]
        ),
        "serialized_library_tokens": tokens,
        "guidance_characters": sum(
            len(s["guidance"])
            if isinstance(s["guidance"], str)
            else len(json.dumps(s["guidance"], ensure_ascii=False))
            for s in bank
        ),
        "not_a_utility_score_or_publication_gate": True,
    }

"""Lossless skill-field serialization, not routing or semantic compilation.

Every original scope, word, conditional relation and record order is preserved.
Only repeated field names move to a shared header. No model, verdict, eviction,
answer operation, score admission or on-error alternative is introduced.
"""

from __future__ import annotations

import copy
import json

from .task_local import SEMANTIC_FIELDS

COLUMNS = ("id", *SEMANTIC_FIELDS)
TABLE_NOTICE = (
    " Applicable skills are lossless rows under skill_table_columns, in that "
    "column order: id, when, inspection, relation_if_established, "
    "evidence_requirement. All original words and public applicability remain. "
    "Read each row as the same named-field record, not an automatic verdict."
)


def encode_skill_projection(projection):
    rows = {}
    for h, records in projection.items():
        rows[h] = []
        for record in records:
            if set(record) != {"id", "guidance"} or set(record["guidance"]) != set(SEMANTIC_FIELDS):
                raise ValueError("Exact original public semantic fields required; never drop extras")
            rows[h].append([record["id"], *[copy.deepcopy(record["guidance"][k]) for k in SEMANTIC_FIELDS]])
    return {"columns": list(COLUMNS), "by_hypothesis": rows}


def decode_skill_projection(table):
    if set(table) != {"columns", "by_hypothesis"} or table["columns"] != list(COLUMNS):
        raise ValueError("Declared exact shared header required; no guessed decoding")
    result = {}
    for h, rows in table["by_hypothesis"].items():
        result[h] = []
        for row in rows:
            if not isinstance(row, list) or len(row) != len(COLUMNS):
                raise ValueError("Incomplete skill row; no padding or default values")
            result[h].append({"id": row[0], "guidance": dict(zip(SEMANTIC_FIELDS, copy.deepcopy(row[1:]), strict=True))})
    return result


def scoped_budget_view(projection):
    # Empty memory has no table/header on the wire. This is the ordinary zero-data
    # input, not an exception path; its existing empty-arm requests stay exact.
    return encode_skill_projection(projection) if any(projection.values()) else projection


def table_skill_messages(messages, delivery):
    result, trace = copy.deepcopy(messages), copy.deepcopy(delivery)
    projection = trace["actual_task_local_projection"]
    trace["actual_task_local_projection_is_lossless_decoded_semantic_view"] = True
    trace["skill_delivery_encoding"] = "scoped_lossless_table_v1"
    trace["actual_wire_skill_table"] = None
    if not any(projection.values()):
        assert result == messages  # No skills: no new header or prompt alteration.
        return result, trace
    table = encode_skill_projection(projection)
    if decode_skill_projection(table) != projection:
        raise ValueError("Lossless skill encoding changed its actual records")
    body = json.loads(result[1]["content"])
    if set(body["hypotheses"]) != set(projection):
        raise ValueError("Exact original hypothesis scope required")
    for h, records in projection.items():
        if body["hypotheses"][h]["applicable_published_skills"] != records:
            raise ValueError("Wire skill records differ from their semantic projection")
        body["hypotheses"][h]["applicable_published_skills"] = table["by_hypothesis"][h]
    body["skill_table_columns"] = list(COLUMNS)
    result[0]["content"] += TABLE_NOTICE
    result[1]["content"] = json.dumps(body, ensure_ascii=False, separators=(",", ":"))
    trace["actual_wire_skill_table"] = table
    return result, trace

