def witness_publication_schema(labels, parent, rows):
    """One global member account plus one condition assessment per edit/case."""
    ids = [r["id"] for r in rows]
    if not rows or len(ids) != len(set(ids)) or any(not r["spans"] for r in rows):
        raise ValueError("Actual distinct nonempty original source window required")
    schema = differential_schema(labels, parent, ids, guidance_schema=LOCAL_GUIDANCE_SCHEMA)
    schema["$defs"] = {
        f"source_{r['id']}_coordinates": {
            "type": "array", "items": {"type": "integer", "minimum": 0, "maximum": len(r["spans"]) - 1},
        } for r in rows
    }
    schema["$defs"]["condition_status"] = {"type": "string", "enum": ["established", "not_established", "unresolved"]}
    accounts = {}
    for h in labels:
        cases = {}
        for row in rows:
            members = row["annotation_sets"][0]["annotations"][h]["spans"]
            cases[str(row["id"])] = {
                "type": "object", "additionalProperties": False,
                "required": [str(i) for i in members],
                "properties": {str(i): {"type": "string", "minLength": 1, "maxLength": 160} for i in members},
            }
        accounts[h] = {"type": "object", "additionalProperties": False, "required": list(cases), "properties": cases}
    schema["properties"] = {
        "training_evidence_accounts": {"type": "object", "additionalProperties": False, "required": list(accounts), "properties": accounts},
        **schema["properties"],
    }
    schema["required"] = ["training_evidence_accounts", *schema["required"]]
    cases = {}
    for row in rows:
        fields = {
            "source_condition_status": {"$ref": "#/$defs/condition_status"},
            "source_condition_evidence": {"$ref": f"#/$defs/source_{row['id']}_coordinates"},
            "brief_boundary_fact": {"type": "string", "minLength": 1, "maxLength": 240},
        }
        cases[str(row["id"])] = {"type": "object", "additionalProperties": False, "required": list(fields), "properties": fields}
    op = schema["properties"]["operations"]["items"]
    existing = op["properties"]
    op["properties"] = {
        "operation": existing["operation"], "target_ids": existing["target_ids"],
        "witness_checks": {"anyOf": [
            {"type": "object", "additionalProperties": False, "required": list(cases), "properties": cases},
            {"type": "object", "additionalProperties": False, "required": [], "properties": {}},
        ]},
        **{k: v for k, v in existing.items() if k not in ("operation", "target_ids")},
    }
    op["required"] = list(op["properties"])
    return schema


def publish_with_training_witnesses(parent, value, labels, rows):
    """Identity checks only; publish semantic disagreements verbatim, not gate."""
    validate(value, witness_publication_schema(labels, parent, rows))
    projected = copy.deepcopy(value)
    accounts = projected.pop("training_evidence_accounts")
    sources = {str(r["id"]): r for r in rows}
    observations, conflicts, unsupported = [], [], []
    accounted = sum(len(members) for cases in accounts.values() for members in cases.values())
    for original, op in zip(value["operations"], projected["operations"], strict=True):
        checks = op.pop("witness_checks")
        skill = op["skill"]
        if skill is None:
            if checks:
                raise ValueError("DELETE has no resulting runtime condition to assess")
            continue
        if set(checks) != set(sources):
            raise ValueError("Witness checks must cover every supplied original source")
        target = skill["guidance"]["relation_if_established"]
        positive_by_h = {h: 0 for h in skill["hypothesis_ids"]}
        for d, entry in checks.items():
            indices = entry["source_condition_evidence"]
            if len(indices) != len(set(indices)):
                raise ValueError("Duplicate original witness coordinates; no deduplication")
            for h in skill["hypothesis_ids"]:
                gold = sources[d]["annotation_sets"][0]["annotations"][h]
                claim = {"skill_id": skill["id"], "hypothesis_id": h, "source_id": int(d),
                         "claimed_condition_status": entry["source_condition_status"], "published_relation": target,
                         "original_Gold_choice": gold["choice"], "brief_boundary_fact": entry["brief_boundary_fact"]}
                observations.append(claim)
                if target is not None and entry["source_condition_status"] == "established":
                    if target != gold["choice"]:
                        conflicts.append(claim)
                    else:
                        positive_by_h[h] += 1
        if target is not None and any(n == 0 for n in positive_by_h.values()):
            unsupported.append(skill["id"])
        assert original["skill"] == skill
    published = apply_differential_publication(parent, projected, labels, [r["id"] for r in rows], guidance_schema=LOCAL_GUIDANCE_SCHEMA)
    return published, projected, {
        "teacher_claims_not_independent_semantic_verification": observations,
        "claimed_established_with_different_original_label": conflicts,
        "nonnull_records_without_claimed_same_label_positive_witness": unsupported,
        "original_Gold_members_explicitly_accounted_once_not_proven_retrieved": accounted,
        "no_semantic_conflict_or_coverage_based_admission_repair_or_bank_choice": True,
    }


class WitnessGroundedStudy(LiteralEvidenceStudy):
    """Not CLI-registered: original native task, table skills, grounded writer."""

    def __init__(self, config_path, *, run_id=None):
        super().__init__(config_path, run_id=run_id)
        if self.cfg.get("teacher_publication_format") != "explicit_witness_accounts_v2":
            raise ValueError("Prospective witness-output policy must be declared explicitly")
        if self.cfg.get("skill_delivery_encoding") != "scoped_lossless_table_v1":
            raise ValueError("Prospective lossless skill delivery must be explicit")

    def make_payload(self, arm, row, bank, model, state):
        messages, schema, plan, trace = super().make_payload(arm, row, bank, model, state)
        messages, delivery = table_skill_messages(messages, trace["task_local_delivery"])
        view = scoped_budget_view(delivery["actual_task_local_projection"])
        delivery["actual_scoped_delivery_tokens"] = self.meter.token_count(text=json.dumps(view, ensure_ascii=False, separators=(",", ":")))
        return messages, schema, plan, {**trace, "task_local_delivery": delivery}

    def validate_library(self, bank):
        for skill in bank:
            validate(skill, skill_record_schema(self.labels, guidance_schema=LOCAL_GUIDANCE_SCHEMA))
            if len(set(skill["hypothesis_ids"])) != len(skill["hypothesis_ids"]) or len(set(skill["guidance"]["source_operations"])) != len(skill["guidance"]["source_operations"]):
                raise ValueError("Duplicate original scope or factual operation")
        projection = task_skill_projection(bank, self.labels)
        master = self.meter.token_count(text=render_library(bank))
        scoped = self.meter.token_count(text=json.dumps(scoped_budget_view(projection), ensure_ascii=False, separators=(",", ":")))
        if max(master, scoped) > self.cfg["library_token_hard_cap"]:
            raise ValueError("Master or actual table projection over declared capacity; no pruning/fallback")
        return {"master_tokens": master, "scoped_delivery_tokens": scoped}

    def update(self, batch):
        tokens = self.validate_library(self.bank)
        packet = bounded_teacher_packet(self.training, batch, self.labels, self.bank, self.state, self.before, self.after, master_tokens=tokens["master_tokens"], cap=self.cfg["library_token_hard_cap"])
        rows = [r for r in self.training if r["id"] in packet["supplied_original_witness_ids"]]
        body = literal_feedback_view(packet, rows)
        body["serialized_parent_scoped_delivery_tokens"] = tokens["scoped_delivery_tokens"]
        body["lawyer_skill_delivery_encoding"] = {
            "format": "scoped_lossless_table_v1", "columns": list(COLUMNS),
            "same_public_scope_and_words_no_semantic_filter_or_verdict": True,
            "semantic_projection_in_observations_is_losslessly_decoded_not_wire_object_spelling": True,
            "training_witness_metadata_never_enters_runtime_table_or_its_token_budget": True,
        }
        value = self.teacher_call(f"task_local_b{batch}", LOCAL_TEACHER_SYSTEM + LITERAL_TEACHER_NOTICE + WITNESS_NOTICE, body, witness_publication_schema(self.labels, self.bank, rows))
        bank, projection, witness_audit = publish_with_training_witnesses(self.bank, value, self.labels, rows)
        capacity = self.validate_library(bank)
        stats = {**publication_statistics(self.bank, projection, bank, capacity["master_tokens"]), "serialized_scoped_delivery_tokens": capacity["scoped_delivery_tokens"]}
        RunStore.immutable_json(self.out / f"update_transactions/b{batch}.json", {
            "at": now(), "batch": batch, "actual_parent": self.bank,
            "actual_teacher_value": value, "publication_input_without_training_only_witness_metadata": projection,
            "teacher_witness_claim_audit_not_admission": witness_audit,
            "publication": bank, "management": stats, "source_case_ids": [r["id"] for r in rows],
            "all_valid_changes_published_without_efficacy_gate": True,
            "actual_current_and_previous_same_parent_window_not_full_cumulative_raw_history": True,
            "no_fixed_skill_count_growth_deletion_or_best_bank_selection": True,
            "new_teacher_invocation_for_this_edit": True,
            "teacher_feedback_view": "literal_evidence_comparisons_v1",
            "teacher_publication_format": "explicit_witness_accounts_v2",
            "skill_delivery_encoding": "scoped_lossless_table_v1",
            "original_annotations_and_actual_answers_not_rewritten": True,
        })
        return bank, stats

"""Report only saved observations; never make model calls or alter a skill."""

from __future__ import annotations

import csv
import io
import json
from pathlib import Path

from legal_skill_guard.experiment.storage import RunStore


def _number(value):
    return "N/A" if value is None else f"{100 * value:.2f}"


def _completed_comparisons(value):
    """The three actual saved completion formats, not inferred/missing results."""
    if "development" in value:
        sections = [("固定末次库的开发迁移评估", value["development"])]
    elif "results" in value:
        sections = [("固定末次库的开发比较", value["results"])]
    elif "main_results" in value and "probe_results" in value:
        sections = [
            ("主开发比较", value["main_results"]),
            ("独立来源交付/示例探针", value["probe_results"]),
        ]
    else:
        raise ValueError("Unrecognized completion format; do not invent a comparison")
    for title, metrics in sections:
        if not metrics:
            raise ValueError(f"Empty completed comparison: {title}")
        sizes = {(m["documents"], m["hypotheses"]) for m in metrics.values()}
        if len(sizes) != 1:
            raise ValueError(f"Inconsistent comparison denominators: {title}")
    return sections


def write_report(run: Path):
    done = run / "completion.json"
    sections = _completed_comparisons(json.loads(done.read_text())) if done.exists() else []
    summaries = [json.loads(p.read_text()) for p in sorted(run.glob("batch*_summary.json"))]
    rows = []
    for summary in summaries:
        phase_keys = (
            (("before", "before"), ("after", "after"))
            if "before" in summary
            else (("before", "before_first_encounter"), ("after", "after_seen_training_fit"))
        )
        strong = summary.get("strong_empty")
        for phase, key in phase_keys:
            for arm, m in summary[key].items():
                rows.append(
                    {
                        "batch": summary["batch"],
                        "phase": phase,
                        "arm": arm,
                        "documents": m["documents"],
                        "hypotheses": m["hypotheses"],
                        "accuracy": m["label_accuracy"],
                        "evidence_precision": m["evidence_tp"]
                        / (m["evidence_tp"] + m["evidence_fp"])
                        if m["evidence_tp"] + m["evidence_fp"]
                        else None,
                        "evidence_recall": m["evidence_tp"] / (m["evidence_tp"] + m["evidence_fn"])
                        if m["evidence_tp"] + m["evidence_fn"]
                        else None,
                        "evidence_micro_f1": m["evidence_micro_f1_gold_non_neutral"],
                        "joint_exact_accuracy": m["joint_exact_accuracy"],
                        "same_batch_strong_accuracy": strong["label_accuracy"]
                        if strong is not None
                        else None,
                        "same_batch_strong_evidence_micro_f1": strong[
                            "evidence_micro_f1_gold_non_neutral"
                        ]
                        if strong is not None
                        else None,
                    }
                )
    stream = io.StringIO()
    if rows:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)
    # Reports are derived, replaceable outputs; immutable native artifacts stay untouched.
    run.mkdir(parents=True, exist_ok=True)
    (run / "training_curve.csv").write_text(stream.getvalue())
    lines = [
        "# 当前运行的真实结果",
        "",
        "before＝本批首次遇到；after＝教师见过本批标签后的拟合。不同批次不等难。",
        "以下依据本Run的显式保存/引用；历史逐请求相同的控制不是新生成或独立重复，不以技能数证明收益。",
        "",
        "|批次|条件|阶段|分类 %|依据 F1 %|联合全对 %|",
        "|---|---|---|---:|---:|---:|",
    ]
    for row in rows:
        lines.append(
            "|"
            + "|".join(str(row[k]) for k in ("batch", "arm", "phase"))
            + "|"
            + "|".join(
                _number(row[k]) for k in ("accuracy", "evidence_micro_f1", "joint_exact_accuracy")
            )
            + "|"
        )
    if done.exists():
        for title, metrics in sections:
            documents, hypotheses = next(
                iter({(m["documents"], m["hypotheses"]) for m in metrics.values()})
            )
            lines += [
                "",
                f"## {title}：每条件{documents}份合同、{hypotheses}个命题",
                "",
                "不是官方测试；命题数不是独立来源数，单个学习副本不支持跨学习稳定性结论。",
                "",
                "|条件|分类 %|依据 F1 %|联合全对 %|",
                "|---|---:|---:|---:|",
            ]
            for arm, m in metrics.items():
                lines.append(
                    "|"
                    + arm
                    + "|"
                    + "|".join(
                        _number(m[k])
                        for k in (
                            "label_accuracy",
                            "evidence_micro_f1_gold_non_neutral",
                            "joint_exact_accuracy",
                        )
                    )
                    + "|"
                )
    else:
        lines += ["", "[PENDING RESULT — 全部终点回答尚未完成，未读取终点评分标签。]"]
    (run / "results.md").write_text("\n".join(lines) + "\n")
    RunStore.atomic_json(
        run / "report_status.json",
        {
            "completed_batches": len(summaries),
            "final_comparison_complete": done.exists(),
            "new_model_calls": 0,
            "new_teacher_calls": 0,
        },
    )
    return {"completed_batches": len(summaries), "final_comparison_complete": done.exists()}

"""Native task and binary original-span membership metrics; no semantic judge."""

from __future__ import annotations

import copy
import json
from collections.abc import Mapping, Sequence
from typing import Any

from jsonschema import validate

CHOICES = ("Entailment", "Contradiction", "NotMentioned")


def coherent_native_schema(schema: Mapping[str, Any]) -> dict[str, Any]:
    """Encode the PUBLIC answer contract before generation, never repair a reply.

    The original scorer deliberately does not call this function: old invalid
    label/evidence combinations retain their actual historical penalties.
    All new treatment and control arms must use the same native constraint.
    """
    result = copy.deepcopy(schema)
    for key, original in result["properties"].items():
        nonneutral, neutral = copy.deepcopy(original), copy.deepcopy(original)
        nonneutral["properties"]["choice"]["enum"] = ["Entailment", "Contradiction"]
        nonneutral["properties"]["spans"]["minItems"] = 1
        neutral["properties"]["choice"]["enum"] = ["NotMentioned"]
        neutral["properties"]["spans"]["maxItems"] = 0
        result["properties"][key] = {"anyOf": [nonneutral, neutral]}
    return result


def marked_text(row: Mapping[str, Any]) -> str:
    parts, recovered, last = [], [], 0
    for index, (start, end) in enumerate(row["spans"]):
        if not (
            type(start) is int and type(end) is int and last <= start < end <= len(row["text"])
        ):
            raise ValueError("Invalid or overlapping original span coordinates")
        gap, span = row["text"][last:start], row["text"][start:end]
        parts.extend((gap, f"<SPAN {index}>", span, f"</SPAN {index}>"))
        recovered.extend((gap, span))
        last = end
    parts.append(row["text"][last:])
    recovered.append(row["text"][last:])
    if "".join(recovered) != row["text"]:
        raise ValueError("Full original contract changed")
    return "".join(parts)


def output_schema(
    row: Mapping[str, Any],
    keys: Sequence[str],
    library: Sequence[Mapping[str, Any]],
    *,
    reporting: bool = True,
) -> dict[str, Any]:
    if len(keys) != len(set(keys)) or not keys:
        raise ValueError("Original hypothesis identities must be distinct and nonempty")
    one: dict[str, Any] = {
        "type": "object",
        "additionalProperties": not reporting,
        "properties": {
            "choice": {"type": "string", "enum": list(CHOICES)},
            "spans": {
                "type": "array",
                "items": {"type": "integer", "enum": list(range(len(row["spans"])))},
            },
        },
        "required": ["choice", "spans"],
    }
    if reporting:
        ids = [s["id"] for s in library]
        if len(ids) != len(set(ids)) or any(not isinstance(i, str) or not i for i in ids):
            raise ValueError("Invalid published skill identities")
        used = (
            {"type": "array", "items": {"type": "string", "enum": ids}}
            if ids
            else {"type": "array", "items": {"type": "string"}, "maxItems": 0}
        )
        one["properties"].update({"reason": {"type": "string"}, "used_skill_ids": used})
        one["required"].extend(("reason", "used_skill_ids"))
    return {
        "type": "object",
        "additionalProperties": False,
        "properties": {key: one for key in keys},
        "required": list(keys),
    }


def render_library(library: Sequence[Mapping[str, Any]]) -> str:
    """The exact lossless library payload used for delivery and capacity metering."""
    return json.dumps(list(library), ensure_ascii=False, separators=(",", ":"))


def solver_messages(
    row: Mapping[str, Any],
    labels: Mapping[str, Any],
    library: Sequence[Mapping[str, Any]],
    system: str,
    *,
    show_span_value_enum_in_prompt: bool = True,
) -> tuple[list[dict[str, str]], dict[str, Any]]:
    """Only original text and public hypotheses; no annotation access here."""
    keys = list(labels)
    schema = output_schema(row, keys, library)
    common = json.loads(json.dumps(schema["properties"][keys[0]]))
    if not show_span_value_enum_in_prompt:
        # Source markers identify the evidence; the native schema enforces its
        # range. Do not duplicate an answer-like numeric candidate list in text.
        common["properties"]["spans"]["items"] = {"type": "integer"}
    body = {
        "full_contract_with_original_span_markers": marked_text(row),
        "hypotheses": {key: labels[key]["hypothesis"] for key in keys},
        "output_contract": {
            "required_hypothesis_keys": keys,
            "common_schema_for_each_hypothesis": common,
            "schema_is_permitted_values_not_current_answers": True,
        },
    }
    rendered = render_library(library)
    messages = [
        {"role": "system", "content": system + "\nReusable skills: " + rendered},
        {"role": "user", "content": json.dumps(body, ensure_ascii=False)},
    ]
    return messages, schema


def original_feedback(
    response: Mapping[str, Any] | None,
    row: Mapping[str, Any],
    gold: Mapping[str, Any],
    keys: Sequence[str],
) -> dict[str, Any]:
    parsed, valid, error = None, False, None
    try:
        if response is None or response["finish_reason"] != "stop":
            raise ValueError("No complete native public answer")
        parsed = json.loads(response["content"])
        validate(parsed, output_schema(row, keys, [], reporting=False))
        valid = True
    except Exception as exc:
        error = repr(exc)
    queries = []
    for key in keys:
        g, prediction = gold[key], parsed[key] if valid else None
        gold_spans = set(g["spans"])
        if g["choice"] not in CHOICES or any(type(i) is not int for i in g["spans"]):
            raise ValueError("Malformed original benchmark annotation")
        nonneutral = g["choice"] != "NotMentioned"
        if bool(gold_spans) != nonneutral:
            raise ValueError("Original evidence presence differs from original class")
        predicted_spans = set(prediction["spans"]) if valid else set()
        tp, fp, fn = (
            len(gold_spans & predicted_spans),
            len(predicted_spans - gold_spans),
            len(gold_spans - predicted_spans),
        )
        f1 = 2 * tp / (2 * tp + fp + fn) if nonneutral else None
        correct = bool(valid and prediction["choice"] == g["choice"])
        queries.append(
            {
                "hypothesis_id": key,
                "gold": g,
                "prediction": prediction,
                "label_correct": correct,
                "gold_non_neutral": nonneutral,
                "evidence_tp": tp,
                "evidence_fp": fp,
                "evidence_fn": fn,
                "evidence_f1_gold_non_neutral": f1,
                "joint_exact": bool(correct and predicted_spans == gold_spans),
                "joint_soft": float(correct) * f1
                if nonneutral
                else float(correct and not predicted_spans),
            }
        )
    return {
        "public_valid": valid,
        "public_error": error,
        "parsed": parsed,
        "queries": queries,
        "native_public_answer_never_rewritten": True,
    }


def original_metrics(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    queries = [q for r in rows for q in r["queries"]]
    if not queries:
        raise ValueError("No original tasks to aggregate")
    positive = [q for q in queries if q["gold_non_neutral"]]
    tp, fp, fn = (sum(q["evidence_" + field] for q in positive) for field in ("tp", "fp", "fn"))
    neutral_correct = [q for q in queries if not q["gold_non_neutral"] and q["label_correct"]]
    return {
        "documents": len(rows),
        "hypotheses": len(queries),
        "label_correct": sum(q["label_correct"] for q in queries),
        "label_accuracy": sum(q["label_correct"] for q in queries) / len(queries),
        "gold_non_neutral_queries": len(positive),
        "evidence_tp": tp,
        "evidence_fp": fp,
        "evidence_fn": fn,
        "evidence_micro_f1_gold_non_neutral": 2 * tp / (2 * tp + fp + fn) if positive else None,
        "evidence_query_mean_f1_gold_non_neutral": sum(
            q["evidence_f1_gold_non_neutral"] for q in positive
        )
        / len(positive)
        if positive
        else None,
        "joint_exact_correct": sum(q["joint_exact"] for q in queries),
        "joint_soft_mean": sum(q["joint_soft"] for q in queries) / len(queries),
        "public_valid_documents": sum(r["public_valid"] for r in rows),
        "length_cutoffs": sum(
            bool(r["response"] and r["response"]["finish_reason"] == "length") for r in rows
        ),
        "class_denominators": {
            label: {
                "n": sum(q["gold"]["choice"] == label for q in queries),
                "correct": sum(
                    q["gold"]["choice"] == label and q["label_correct"] for q in queries
                ),
            }
            for label in CHOICES
        },
        "correct_nm_with_nonempty_evidence": sum(
            bool(q["prediction"]["spans"]) for q in neutral_correct
        ),
        "correct_nm_with_empty_evidence": sum(
            not q["prediction"]["spans"] for q in neutral_correct
        ),
        "nonneutral_label_and_all_evidence_correct": sum(q["joint_exact"] for q in positive),
        "reported_skill_use_queries": sum(
            bool(q["prediction"] and q["prediction"].get("used_skill_ids")) for q in queries
        ),
        "reported_skill_use_not_internal_causal_proof": True,
        "usage": {
            field: sum((r["response"] or {})[field] if r["response"] else 0 for r in rows)
            for field in ("prompt_tokens", "completion_tokens")
        },
    }

"""Stable hashing helpers used by data and run manifests."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def canonical_json_sha256(value: Any) -> str:
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()
